"use client";

import { useState } from "react";
import { useCart } from "@/app/store/cart";
import { X, Plus, Minus } from "lucide-react";

interface FoodItemModalProps {
  item: any;
  onClose: () => void;
  onAddToCart?: () => void;
}

export default function FoodItemModal({ item, onClose, onAddToCart }: FoodItemModalProps) {
  const addItem = useCart((s) => s.addItem);
  const [qty, setQty] = useState(1);
  const [size, setSize] = useState(item.sizes?.[0]);
  const total = size.price * qty;

  const handleAddToCart = () => {
    addItem({
      productId: item.id,
      name: item.name,
      sizeLabel: size.size_label,
      price: size.price,
      qty,
      veg: item.veg,
    });
    
    if (onAddToCart) {
      onAddToCart();
    }
    
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />
      
      {/* Modal - Bottom Sheet */}
      <div className="relative w-full max-w-lg bg-white rounded-t-xl p-4 max-h-[85vh] overflow-auto animate-slide-up">
        {/* Header */}
        <div className="flex justify-between items-center mb-3">
          <h2 className="font-semibold text-lg">
            {item.veg ? "🟢" : "🔴"} {item.name}
          </h2>
          <button onClick={onClose}>
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Image */}
        {item.images?.[0] && (
          <img
            src={item.images[0].image_url}
            alt={item.name}
            className="w-full h-48 object-cover rounded-lg mb-3"
          />
        )}

        {/* Description */}
        {item.description && (
          <p className="text-sm text-gray-600 mb-3">
            {item.description}
          </p>
        )}

        {/* Size Selector */}
        {item.sizes?.length > 1 && (
          <div className="mb-4">
            <p className="font-medium mb-2">Choose Size</p>
            <div className="flex gap-2 flex-wrap">
              {item.sizes.map((s: any) => (
                <button
                  key={s.id}
                  onClick={() => setSize(s)}
                  className={`border px-3 py-1 rounded text-sm ${
                    size.id === s.id
                      ? "border-black font-semibold"
                      : ""
                  }`}
                >
                  {s.size_label} – ₹{s.price}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Quantity */}
        <div className="flex items-center gap-4 mb-4">
          <p className="font-medium">Quantity</p>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setQty(Math.max(1, qty - 1))}
              className="w-8 h-8 rounded-full border flex items-center justify-center"
            >
              <Minus className="w-3 h-3" />
            </button>
            <span className="w-8 text-center">{qty}</span>
            <button
              onClick={() => setQty(qty + 1)}
              className="w-8 h-8 rounded-full border flex items-center justify-center"
            >
              <Plus className="w-3 h-3" />
            </button>
          </div>
        </div>

        {/* Add to Cart */}
        <button
          onClick={handleAddToCart}
          className="bg-black text-white w-full py-3 rounded-lg font-semibold"
        >
          Add to Cart • ₹{total}
        </button>
      </div>
    </div>
  );
}